  console.log('[DEBUG navigateToSubfolder] folderId:', folderId, 'folderName:', folderName, 'keys:', keys.map(k => `${k.keyType}:${k.itemId}`));

  // Find the re-wrapped folder key for this subfolder
  const keyRecord = keys.find((k) => k.keyType === 'folder' && k.itemId === folderId);
  if (!keyRecord) {
    console.error('[DEBUG navigateToSubfolder] No key found! Available keys:', JSON.stringify(keys.map(k => ({ type: k.keyType, id: k.itemId }))));
    throw new Error('No key available for this subfolder');
  }

